        "Yahweh’s Passover",
        "word",
        "Hebrew",
        "Hebrew",
        "<strong>Pesach (<em>פֶּסַח</em>) — “passover” or “protective limping.”</strong> The verb <em>pasach</em> appears only in this and a handful of related passages. Traditional reading: God “passed over” the Hebrew houses. Recent semitic comparison (Akkadian <em>pasāhu</em>, “to placate”) and Isaiah 31:5’s parallel of YHWH “hovering / protecting” suggest the verb may originally have meant a protective stance — God stood guard over the doorways rather than skipping them. The Hebrew bears both senses.",
        "User original",
