        "Note",
        "Note",
        "<strong>“A kingdom of priests, and a holy nation.”</strong> The phrase democratizes priesthood — every Israelite is, at least in vocation, a priest mediating between the holy and the world. The Aaronic priesthood that follows in Leviticus is in tension with this opening promise. 1 Peter 2:9 picks up the same line and applies it to the church.",
