        "",
        "the Urim and the Thummim",
        "comm",
        "Note",
        "Note",
        '<strong>Urim and Thummim.</strong> Two unidentified objects ("lights and perfections," approximately) used by the high priest to discern divine decisions, probably some kind of cleromancy (lot-casting). They figure in 1 Sam 14:41, 28:6 and elsewhere. After the early monarchy they fall out of use; Ezra 2:63 / Neh 7:65 mentions priests waiting for "a priest with Urim and Thummim" as if the practice were already lost. The institution disappears entirely by the Second Temple era.',
        "User original",
