    (
        36,
        8,
        "",
        "ten curtains of fine twined linen, blue, purple, and scarlet",
        "comm",
        "Note",
        "Note",
        '<strong>The tabernacle textile economy.</strong> The chapter records the actual production of the ten inner curtains — each 28 cubits long by 4 wide, with cherubim woven in. The materials catalog of the chapter as a whole (gold, silver, bronze, blue, purple, scarlet, linen, goats’ hair, ram skins, badger skins, acacia wood, oil, spices, onyx) represents the most expensive textile-and-metallurgical project the wilderness-camp could manage, drawn entirely from the spoils of Egypt (12:35–36, "Israel asked the Egyptians for articles of silver and gold and clothing"). The Egyptian wealth that financed Israelite oppression in chs 1–11 becomes, post-exodus, the literal material substance of Israelite worship. The theological inversion is precise: the wages of slavery are sublimated into the architecture of divine encounter. The chapter is one of the OT’s most elaborate displays of how the redeemed community’s worship is built from materials gathered through their prior suffering.',
        "User original",
    ),
    (
        36,
        8,
        "a",
        "man",
        "lang-hebrew",
        "Hebrew",
        "Hebrew.",
        "<strong>ʼâdâm (<em>אָדָם</em>).</strong> ruddy i.e. a human being (an individual or the species, mankind, etc.). <em>[Reviewer: extend this with context, theological reading, and any cross-canon resonance before promoting.]</em>",
        "Strong's H120, A Concise Dictionary of the Words in the Hebrew Bible, James Strong (1894). PD.",
    ),
    (
        36,
        38,
        "",
        "their five sockets were of bronze",
        "comm-contextual",
        "Note",
        "Note",
        "<strong>The metal hierarchy.</strong> The tabernacle’s precious-metal usage is graded by sanctuary-zone proximity: gold dominates the most holy place and the immediately surrounding furniture (the ark, the cherubim, the table, the lampstand, the altar of incense), silver appears in the structural sockets supporting the framework, and bronze is used for the courtyard altar and basin and for outer-zone fittings (here, the screen pillars’ sockets). The pattern encodes architectural theology: increasing metallic value as one approaches the divine throne. The same gradient governs ANE temple architecture broadly (Mesopotamian and Phoenician temples follow similar precious-metal hierarchies), and Solomon’s temple intensifies it with even more gold. Daniel 2’s vision of the four-metal statue (gold head, silver chest, bronze thighs, iron legs) inverts the gradient as a vision of declining empire, deliberately playing against the tabernacle’s ascending gradient — Daniel’s metals decline from king to king as the tabernacle’s metals ascend toward the divine center.",
        "User original",
    ),
    (
        37,
        1,
        "",
        "Bezalel made the ark of acacia wood",
        "comm-ethiopian",
        "Note",
        "Note",
        "<strong>The ark’s construction.</strong> The verse reports the actual construction of the most sacred object in Israelite religion: the wooden box that held the tablets of the covenant, with its gold-plated cherubim throne above. The ark’s eventual disappearance from history is one of the great mysteries of biblical archaeology — it was last definitively located in Solomon’s temple (1 Kgs 8:6, brought into the holy of holies; 2 Chr 35:3, mentioned in Josiah’s reign) and is presumed lost or hidden in the Babylonian destruction of 586 BCE. Jewish tradition preserves multiple legends: the ark was hidden by Jeremiah in a cave on Mount Nebo (2 Macc 2:4–8), or in a chamber beneath the temple mount (b. Yoma 53b–54a). The Ethiopian church preserves a tradition that the ark was brought from Solomon’s court by Menelik I, son of Solomon and the Queen of Sheba, and resides today in a chapel at Aksum (cf. the <em>Kebra Nagast</em>). The verse marks the construction of an object that, materially or legendarily, has shaped sacred geography across three continents.",
        "User paraphrase; references Kebra Nagast",
    ),
